        if not cells:
            continue
        pr0, pr1 = min(r for r, _ in cells), max(r for r, _ in cells)
        pc0, pc1 = min(x for _, x in cells), max(x for _, x in cells)
        patch = [grid[r][pc0:pc1 + 1] for r in range(pr0, pr1 + 1)]
        for r in range(r0, r1 + 1):
            for j, x in enumerate(range(pc0, pc1 + 1)):
                if out[r][x] == 0:
                    out[r][x] = patch[(r - pr0) % len(patch)][j]

    # Horizontal rulers repeat a vertical/rectangular patch across columns.
    for r in range(h):
